mapper.select:
SELECT id, facility_name, facility_type, address, contract_power_kw, created_at
FROM company_facilities
WHERE id = #{id}

mapper.update:
UPDATE company_facilities
SET facility_name    = #{facilityName},
    facility_type    = #{facilityType},
    address          = #{address},
    contract_power_kw = #{contractPowerKw}
WHERE id = #{id}
